    const adapter = new AoCliAdapter({ command: async () => { kills += 1; return { stdout: '', stderr: '' }; } });
    await adapter.stop('worker', 'input stalled');
    await adapter.stop('worker', 'attempt finished');
    expect(kills).toBe(1);
